const SORT_SELECTED_ICON_COLOR = '#ECE8E4'
const COLOR_VALUES_TO_REPLACE = new Set(['black', '#000', '#000000', '#1e120d'])

const shouldReplaceIconColor = (value) => {
	if (typeof value !== 'string') return false
	return COLOR_VALUES_TO_REPLACE.has(value.trim().toLowerCase())
}

const toSelectedIcon = (node) => {
	if (!isValidElement(node)) return node

	const nextProps = {}
	if (shouldReplaceIconColor(node.props.fill)) {
		nextProps.fill = SORT_SELECTED_ICON_COLOR
	}
	if (shouldReplaceIconColor(node.props.stroke)) {
		nextProps.stroke = SORT_SELECTED_ICON_COLOR
	}

	if (node.props.children) {
		nextProps.children = Children.map(node.props.children, (child) => toSelectedIcon(child))
	}

	return cloneElement(node, nextProps)
}

